window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/09_database_and_storage/09_performance_and_optimisation.md"] = [{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:6145c817fb2584cb:1","question":"<p>(L1 [T]) Что такое query planning?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":19},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cee17dddbf9b4c52:1","question":"<p>(L1 [T]) Зачем СУБД строит план выполнения запроса?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":26},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cd10d2801feefd35:1","question":"<p>(L1 [T]) Чем logical plan отличается от physical plan?</p>\n","answer":"<p><strong>Ответ:</strong> Physical replication передаёт engine/page/log изменения, logical — значения/операции по логической модели. Logical даёт гибкость schema/targets, но требует identity, ordering, DDL/sequence handling и conflict semantics; совместимость отличается. Logical plan описывает смысл операций, physical plan выбирает algorithms/access paths/order/distribution. Несколько физических планов реализуют один logical result, но order/partition properties и memory/IO cost различаются.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a>; <a href=\"https://www.postgresql.org/docs/current/logical-replication.html\">PostgreSQL: Logical replication</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":33},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b6476221051c52ed:1","question":"<p>(L1 [T]) Почему один и тот же SQL можно выполнить несколькими способами?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":40},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:514d4fa7220aeb91:1","question":"<p>(L1 [T]) Что такое access path?</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":47},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:afd261eee5b98074:1","question":"<p>(L1 [T]) Почему planner выбирает между full scan и index scan?</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":54},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c098cf5de5392876:1","question":"<p>(L1 [T]) Что такое filter, projection, join, aggregation в плане?</p>\n","answer":"<p><strong>Ответ:</strong> Filter отбирает строки, projection вычисляет/выбирает поля, join соединяет наборы, aggregation сворачивает группы. Порядок безопасных преобразований влияет на размеры промежуточных данных; NULL/outer semantics ограничивают reorder.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":61},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d9697d7cb2e64077:1","question":"<p>(L1 [T]) Что такое plan node / operator?</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":68},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7bd5c9e43eade681:1","question":"<p>(L1 [T]) Почему порядок операций влияет на производительность?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":75},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:84b220046fb220af:1","question":"<p>(L1 [T]) Почему “правильный SQL” не гарантирует “быстрый SQL”?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":82},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1493bc01c156f240:1","question":"<p>(L1 [P]) Реализовать AST для простого SELECT ... WHERE</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":89},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7bc0f35cc98feb72:1","question":"<p>(L1 [P]) Реализовать logical plan для фильтра и проекции</p>\n","answer":"<p><strong>Ответ:</strong> Tokenizer/parser создаёт typed AST, binder разрешает schema/columns, затем logical operators с явными NULL/types. Optimizer меняет только доказанно equivalent expression/plan; ошибки и unsupported syntax возвращаются явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":96},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a5894c18411fd92c:1","question":"<p>(L1 [P]) Реализовать physical plan: seq scan vs index lookup</p>\n","answer":"<p><strong>Ответ:</strong> Logical plan описывает смысл операций, physical plan выбирает algorithms/access paths/order/distribution. Несколько физических планов реализуют один logical result, но order/partition properties и memory/IO cost различаются. Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования. Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":103},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b80745452f7bb920:1","question":"<p>(L1 [P]) Реализовать tree printer для execution plan</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":110},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:15c55322c76b11bd:1","question":"<p>(L1 [P]) Реализовать simple planner для single-table queries</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":117},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fa7bab3de10c02c8:1","question":"<p>(L2 [T]) Что такое predicate pushdown на уровне planner?</p>\n","answer":"<p><strong>Ответ:</strong> Pushdown/pruning уменьшают работу до materialization/shipping, только если преобразование сохраняет semantics. Metadata min/max позволяют пропустить блок лишь при доказанном отсутствии совпадений, включая NULL/collation правила.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a></p>\n","group":"🔹 Query planning","line":124},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e1219880628e3b78:1","question":"<p>(L2 [T]) Почему join order — одна из самых дорогих частей planning?</p>\n","answer":"<p><strong>Ответ:</strong> Порядок joins определяет размеры промежуточных наборов; ошибка cardinality раньше по плану может умножить downstream работу. Перестановка ограничена semantics outer joins/lateral/volatile expressions, а не только cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":131},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:754f155bf5dcf34a:1","question":"<p>(L2 [T]) Что такое cardinality estimation?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":138},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:64a895de57579c77:1","question":"<p>(L2 [T]) Почему planner должен учитывать доступные индексы?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":145},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a3dae24a45463e07:1","question":"<p>(L2 [T]) Что такое plan enumeration?</p>\n","answer":"<p><strong>Ответ:</strong> Добавление enum value может сломать старый код с исчерпывающим switch/validation; удаление/сужение ломает уже сохранённые значения. Нужны unknown-value handling, version policy и migration существующих данных.</p>\n<p><strong>Источник:</strong> <a href=\"https://protobuf.dev/programming-guides/proto3/#updating\">Protocol Buffers: Updating a message type</a>; <a href=\"https://www.postgresql.org/docs/current/sql-altertable.html\">PostgreSQL: ALTER TABLE</a></p>\n","group":"🔹 Query planning","line":152},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7473602ed16724a9:1","question":"<p>(L2 [T]) Почему planning time itself может быть non-trivial?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":159},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:acaaf4b2ae19a28e:1","question":"<p>(L2 [T]) Что такое parameterized plan?</p>\n","answer":"<p><strong>Ответ:</strong> Parameterized path/plan зависит от внешних bind/outer-row параметров; стоимость может сильно меняться по значениям. Нужно отличать generic prepared plan и inner index path nested-loop, уточнив terminology engine.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":166},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cab9ad77f381a983:1","question":"<p>(L2 [T]) Почему prepared statements могут менять качество плана?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":173},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a26dbc48b274fd0c:1","question":"<p>(L2 [T]) Что такое covering plan / index-only plan?</p>\n","answer":"<p><strong>Ответ:</strong> В PostgreSQL index-only scan избегает heap fetch, когда visibility map подтверждает all-visible page. Частые writes/недостаточный VACUUM уменьшают эффект даже при полном covering index. Covering требует наличия всех полей query в index, включая predicates/order, но не гарантирует index-only физическое чтение. Payload columns и широкий composite key увеличивают размер и write maintenance.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/routine-vacuuming.html\">PostgreSQL: Routine vacuuming</a></p>\n","group":"🔹 Query planning","line":180},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:421ac5939caa2602:1","question":"<p>(L2 [T]) Почему planner важен даже в KV/Document системах, а не только в SQL БД?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":187},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bd78efca1d183c90:1","question":"<p>(L2 [P]) Реализовать выбор seq scan vs index scan по селективности</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями. Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования. Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":194},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:115e1ff58adc4f45:1","question":"<p>(L2 [P]) Реализовать pushdown фильтра в scan node</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":201},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5a5c08c121c1b01a:1","question":"<p>(L2 [P]) Реализовать reordering простых conjunctive predicates</p>\n","answer":"<p><strong>Ответ:</strong> Стабильно кодировать key/tokens, выбирать owner и distinct fault-domain replicas по общей versioned membership. Симулировать join/leave/weights, считать moved keys и requests/bytes skew; перенос данных/cutover не подменяется пересчётом hash.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":208},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ae9b9cd8b5e1e9a0:1","question":"<p>(L2 [P]) Реализовать simple join planner для двух таблиц</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":215},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:87d58452e927435e:1","question":"<p>(L2 [P]) Реализовать estimation-based plan selector</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":222},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:18e58a26c7297a38:1","question":"<p>(L2 [D]) Почему planner выбрал full scan вместо очевидного индекса?</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования. Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":229},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7faeba448b8fce47:1","question":"<p>(L2 [D]) Почему после добавления WHERE запрос стал медленнее?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":236},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:415f79bab8d84b7e:1","question":"<p>(L2 [D]) Почему prepared statement даёт худший план, чем ad-hoc query?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":243},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:33e1caf7295a142f:1","question":"<p>(L2 [D]) Почему planning time внезапно стал заметным на коротких запросах?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":250},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:daafe5918e80324a:1","question":"<p>(L2 [D]) Почему один и тот же запрос иногда получает разные планы?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":257},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:0eb0e7ab4a33a858:1","question":"<p>(L3 [T]) Как planner связывает parser, catalog, statistics и optimizer?</p>\n","answer":"<p><strong>Ответ:</strong> Routing metadata должна иметь authority/version, а cached route — способ обнаружить stale epoch и обновиться. TTL cache сам по себе не защищает write ownership; сервер отвергает старую authority и даёт контролируемый retry/redirect.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a>; <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a></p>\n","group":"🔹 Query planning","line":264},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:241d93305cd3f3a0:1","question":"<p>(L3 [T]) Как устроен search space для join ordering?</p>\n","answer":"<p><strong>Ответ:</strong> Порядок joins определяет размеры промежуточных наборов; ошибка cardinality раньше по плану может умножить downstream работу. Перестановка ограничена semantics outer joins/lateral/volatile expressions, а не только cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":271},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e237a967e3993339:1","question":"<p>(L3 [T]) Почему bushy plans дороже оптимизировать, но иногда полезнее?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":278},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c1c569cdfd47301d:1","question":"<p>(L3 [T]) Что такое top-down vs bottom-up planning?</p>\n","answer":"<p><strong>Ответ:</strong> Planner search может строиться снизу вверх dynamic programming либо сверху вниз через memo/rules и physical requirements. Search space grows combinatorially, поэтому pruning/budgets/heuristics обязательны; semantic equivalence проверяется отдельно от cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":285},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fd1082b4c7f44455:1","question":"<p>(L3 [T]) Как planner учитывает physical properties: order, partitioning, distribution?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":292},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fbf8c74ad21bddae:1","question":"<p>(L3 [T]) Как planner должен учитывать CPU vs I/O vs memory trade-offs?</p>\n","answer":"<p><strong>Ответ:</strong> Planner search может строиться снизу вверх dynamic programming либо сверху вниз через memo/rules и physical requirements. Search space grows combinatorially, поэтому pruning/budgets/heuristics обязательны; semantic equivalence проверяется отдельно от cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":299},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d733da909216b274:1","question":"<p>(L3 [T]) Как parameter sniffing влияет на quality плана?</p>\n","answer":"<p><strong>Ответ:</strong> Один cached/generic plan может быть неудачен для skewed parameter values. Сравнить реальные bind values, generic/custom plan, statistics и actual rows; отключение cache глобально может добавить заметный planning overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":306},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5162b3e0eca389ff:1","question":"<p>(L3 [T]) Почему статистики и planner связаны жёстче, чем кажется?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":313},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ae922893781a7696:1","question":"<p>(L3 [T]) Как planner должен учитывать MVCC visibility cost?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":320},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:83501f5e8e1ae6f9:1","question":"<p>(L3 [T]) Почему planner — это не просто rule engine, а часть performance-critical architecture?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":327},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7e3bde4b3340beb1:1","question":"<p>(L3 [P]) Реализовать dynamic programming join enumerator</p>\n","answer":"<p><strong>Ответ:</strong> Построить bounded operators с typed batches, NULL/equality rules и explicit blocking state. Hash/sort stages имеют memory budget/spill и merge semantics; test empty/duplicate/skewed input, cancellation и correctness против простой реализации.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":334},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b431c927f92fa4fd:1","question":"<p>(L3 [P]) Реализовать propagation physical properties в plan tree</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":341},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fcf906e04a011952:1","question":"<p>(L3 [P]) Реализовать parameter-sensitive plan selection</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":348},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:eef8743eb5f7c252:1","question":"<p>(L3 [P]) Реализовать planner trace/debug output</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":355},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:59b2fa3b9a78526d:1","question":"<p>(L3 [P]) Реализовать benchmark planning time vs execution time</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать dataset/seed, целевой profile операций, одинаковую durability и correctness oracle. Сравнивать cold/warm, concurrency/QD и steady-state maintenance, измеряя finished ops/bytes, p50/p99 и errors; менять один исследуемый параметр и исключить setup из таймера.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"🔹 Query planning","line":362},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2323cb7c955506df:1","question":"<p>(L3 [D]) Как доказать, что проблема в planner, а не в execution engine?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":369},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5c9463965297dacd:1","question":"<p>(L3 [D]) Почему при одинаковом SQL разные literals радикально меняют план?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":376},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d0945f14cb2c8cbc:1","question":"<p>(L3 [D]) Как расследовать planner regression после обновления статистик?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":383},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:805dd576e63d207d:1","question":"<p>(L3 [D]) Почему оптимизация join order взорвала CPU на planning phase?</p>\n","answer":"<p><strong>Ответ:</strong> Порядок joins определяет размеры промежуточных наборов; ошибка cardinality раньше по плану может умножить downstream работу. Перестановка ограничена semantics outer joins/lateral/volatile expressions, а не только cost. Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":390},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e7cb2083ff90dc42:1","question":"<p>(L3 [D]) Как найти, что bottleneck — это misestimated cardinality, а не плохой алгоритм join?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения. Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Query planning","line":397},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b1043033683cc05b:1","question":"<p>(L4 [S]) Когда planner можно держать простым rule-based, а когда нужен полноценный optimizer?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":404},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:07c95ab12a2c2b1c:1","question":"<p>(L4 [S]) Как проектировать planner для своей C/C++ БД без взрывной сложности?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":411},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f3b1fdf31e34421c:1","question":"<p>(L4 [S]) Как балансировать planning time и plan quality?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":418},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5c93cf1b59e339c7:1","question":"<p>(L4 [S]) Как строить observability для planner/optimizer с первого дня?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны metrics и traces по shard/tenant/region/stage с ограниченной cardinality, а не только общий health. Разделять queue wait, service, I/O, replication и retries, сохранять operation/epoch context без утечки payload/секретов.</p>\n<p><strong>Рекомендация:</strong> Начать с good/eligible SLI и freshness/durability indicators, затем диагностические dimensions. Назначить владельцев/runbooks и проверить alerts на drills, контролируя стоимость и конфиденциальность telemetry.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a></p>\n","group":"🔹 Query planning","line":425},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8cf470859a1fe57a:1","question":"<p>(L4 [S]) Как объяснять продуктовой команде, что “быстрый SQL” зависит от planner semantics, а не только от железа?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Query planning","line":434},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7fe7580c0238bbd1:1","question":"<p>(L1 [T]) Что такое cost-based optimizer (CBO)?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":445},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:29936fd638ec5db0:1","question":"<p>(L1 [T]) Чем CBO отличается от rule-based optimizer?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":452},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4958d2ffec94416c:1","question":"<p>(L1 [T]) Что такое cost model?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":459},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:291b5320769a40d7:1","question":"<p>(L1 [T]) Почему optimizer оценивает несколько альтернативных планов?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":466},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2ffd558a06951998:1","question":"<p>(L1 [T]) Какие ресурсы обычно входят в cost: CPU, I/O, memory?</p>\n","answer":"<p><strong>Ответ:</strong> Planner search может строиться снизу вверх dynamic programming либо сверху вниз через memo/rules и physical requirements. Search space grows combinatorially, поэтому pruning/budgets/heuristics обязательны; semantic equivalence проверяется отдельно от cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":473},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2e4ad32b3feae1ce:1","question":"<p>(L1 [T]) Почему селективность предиката важна для CBO?</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":480},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f2ad1962bfc291d6:1","question":"<p>(L1 [T]) Что такое statistics?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":487},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:efd92562d97af83b:1","question":"<p>(L1 [T]) Почему плохие statistics ведут к плохим планам?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":494},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b1deb0be5b906bc5:1","question":"<p>(L1 [T]) Что такое cardinality estimate?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":501},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ef1bfce5ac7f2474:1","question":"<p>(L1 [T]) Почему CBO никогда не знает будущий runtime точно?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model использует неполную статистику и упрощённые resource assumptions; concurrency/cache/parameter skew меняются во время выполнения. Поэтому estimated cheapest не обязан быть fastest, а regression проверяется actual plan и workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":508},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e3e0c4d436e33664:1","question":"<p>(L1 [P]) Реализовать простую cost model: seq scan cost vs index scan cost</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":515},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:6bdd6c4c45b31012:1","question":"<p>(L1 [P]) Реализовать выбор cheapest plan из двух альтернатив</p>\n","answer":"<p><strong>Ответ:</strong> Задать затраты scan, lookup, sort/join и shipping с явными единицами, оценки selectivity и cumulative rows. Калибровать на измерениях, проверять orders-of-magnitude ошибки и не подменять correctness стоимостным эвристическим правилом.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":522},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cce1204fc4c9adf4:1","question":"<p>(L1 [P]) Реализовать selectivity estimate для equality predicate</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями. Задать затраты scan, lookup, sort/join и shipping с явными единицами, оценки selectivity и cumulative rows. Калибровать на измерениях, проверять orders-of-magnitude ошибки и не подменять correctness стоимостным эвристическим правилом.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":529},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d72e7894f93fcfd7:1","question":"<p>(L1 [P]) Реализовать histogram-based estimate (упрощённо)</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные. Задать затраты scan, lookup, sort/join и shipping с явными единицами, оценки selectivity и cumulative rows. Калибровать на измерениях, проверять orders-of-magnitude ошибки и не подменять correctness стоимостным эвристическим правилом.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":536},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:9c80cb5f5194cb60:1","question":"<p>(L1 [P]) Реализовать join cost estimate для nested loop и hash join</p>\n","answer":"<p><strong>Ответ:</strong> Построить bounded operators с typed batches, NULL/equality rules и explicit blocking state. Hash/sort stages имеют memory budget/spill и merge semantics; test empty/duplicate/skewed input, cancellation и correctness против простой реализации.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":543},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:02a7e57ddea5b7a7:1","question":"<p>(L2 [T]) Что такое histogram и зачем он нужен optimizer-у?</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":550},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d00a39738022d5e5:1","question":"<p>(L2 [T]) Что такое NDV (number of distinct values)?</p>\n","answer":"<p><strong>Ответ:</strong> NDV — оценка числа различных значений в заданном наборе/колонке. Она влияет на selectivity, group cardinality и memory; NULL, correlations и skew требуют явной модели, а не независимых uniform assumptions.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":557},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b637096ec1df4cb4:1","question":"<p>(L2 [T]) Почему предположение independence between predicates часто ошибочно?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":564},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:36aa5c02831347b6:1","question":"<p>(L2 [T]) Почему skew ломает cost model?</p>\n","answer":"<p><strong>Ответ:</strong> Равномерное число keys/bytes не гарантирует равномерный traffic или join work. Измерять heat по ключам/partitions и стоимость операций; hot single key отличается от множества неравномерно распределённых keys.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":571},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:475cf05b4cb79654:1","question":"<p>(L2 [T]) Как optimizer оценивает cost join order?</p>\n","answer":"<p><strong>Ответ:</strong> Порядок joins определяет размеры промежуточных наборов; ошибка cardinality раньше по плану может умножить downstream работу. Перестановка ограничена semantics outer joins/lateral/volatile expressions, а не только cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":578},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:9d543bf7885f1510:1","question":"<p>(L2 [T]) Почему memory budget влияет на выбор плана?</p>\n","answer":"<p><strong>Ответ:</strong> Planner search может строиться снизу вверх dynamic programming либо сверху вниз через memo/rules и physical requirements. Search space grows combinatorially, поэтому pruning/budgets/heuristics обязательны; semantic equivalence проверяется отдельно от cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":585},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:3fb5e9158fe65946:1","question":"<p>(L2 [T]) Что такое spill risk в cost model?</p>\n","answer":"<p><strong>Ответ:</strong> Hash/sort spill переносит промежуточные данные на временный storage при недостаточном memory budget. Увеличение per-operator memory умножается на operators/workers/queries и может вызвать OOM; сначала проверить cardinality и concurrency.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":592},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fcaa5ae6b0c93773:1","question":"<p>(L2 [T]) Почему optimizer должен учитывать cost сортировки?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":599},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:60dc53b9f0bd7c1a:1","question":"<p>(L2 [T]) Что такое startup cost vs total cost?</p>\n","answer":"<p><strong>Ответ:</strong> Startup cost — работа до первой выдачи, total — до всего результата. При LIMIT/interactive stream план с низким startup может выиграть у более дешёвого полного scan; blocking sort требует сначала обработать большой набор.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":606},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:0d4ba34a97115aa9:1","question":"<p>(L2 [T]) Почему cheaper estimated plan может быть медленнее в реальности?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model использует неполную статистику и упрощённые resource assumptions; concurrency/cache/parameter skew меняются во время выполнения. Поэтому estimated cheapest не обязан быть fastest, а regression проверяется actual plan и workload. Estimated plan показывает оценки без выполнения, actual добавляет наблюдённые rows/loops/timing/buffers после исполнения. EXPLAIN ANALYZE реально выполняет запрос, в том числе изменяющий, и добавляет measurement overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":613},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5a0873a5fce3292f:1","question":"<p>(L2 [P]) Реализовать multi-column selectivity estimate (упрощённо)</p>\n","answer":"<p><strong>Ответ:</strong> Tuple comparator задаёт lexicographic key order и NULL/collation rules, bounds выражают допустимый prefix/range. Search и updates используют тот же encoding, string-prefix upper bound не всегда простое увеличение byte.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":620},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:da9257c99ecd07b0:1","question":"<p>(L2 [P]) Реализовать cost для sort + merge join</p>\n","answer":"<p><strong>Ответ:</strong> Построить bounded operators с typed batches, NULL/equality rules и explicit blocking state. Hash/sort stages имеют memory budget/spill и merge semantics; test empty/duplicate/skewed input, cancellation и correctness против простой реализации.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":627},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:400051b77fb3cee0:1","question":"<p>(L2 [P]) Реализовать memory-aware выбор hash join vs sort-merge join</p>\n","answer":"<p><strong>Ответ:</strong> Построить bounded operators с typed batches, NULL/equality rules и explicit blocking state. Hash/sort stages имеют memory budget/spill и merge semantics; test empty/duplicate/skewed input, cancellation и correctness против простой реализации.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":634},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:457a0ffaff84f0b6:1","question":"<p>(L2 [P]) Реализовать startup-vs-total cost chooser</p>\n","answer":"<p><strong>Ответ:</strong> Startup cost — работа до первой выдачи, total — до всего результата. При LIMIT/interactive stream план с низким startup может выиграть у более дешёвого полного scan; blocking sort требует сначала обработать большой набор. Задать затраты scan, lookup, sort/join и shipping с явными единицами, оценки selectivity и cumulative rows. Калибровать на измерениях, проверять orders-of-magnitude ошибки и не подменять correctness стоимостным эвристическим правилом.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":641},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:9a732d9195f08bdd:1","question":"<p>(L2 [P]) Реализовать statistics catalog для optimizer-а</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":648},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:88f6491b80e0255d:1","question":"<p>(L2 [D]) Почему optimizer выбрал hash join, а nested loop оказался быстрее?</p>\n","answer":"<p><strong>Ответ:</strong> Hash join строит hash table одной стороны и probe другой; выгоден для соответствующих equality predicates. Build cardinality/width и memory limit определяют spill, skew может создать перегруженный partition. Nested loop выполняет inner path для каждой outer row, поэтому rows×loops важны. При малом outer и indexed inner он эффективен, при ошибке оценки превращается в огромное число probes. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":655},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7d7f12aef92f5dc0:1","question":"<p>(L2 [D]) Почему после ANALYZE план ухудшился?</p>\n","answer":"<p><strong>Ответ:</strong> Устаревшие/недостаточные statistics искажает rows/selectivity, меняя join/index decisions. ANALYZE полезен, но sampling/skew/correlations остаются; сравнить estimates и actual до и после, не форсировать план вслепую. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":662},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c5d715888d2f0c4d:1","question":"<p>(L2 [D]) Почему skew по одному значению ломает оценку cost?</p>\n","answer":"<p><strong>Ответ:</strong> Равномерное число keys/bytes не гарантирует равномерный traffic или join work. Измерять heat по ключам/partitions и стоимость операций; hot single key отличается от множества неравномерно распределённых keys. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":669},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fe7b92457fca53e5:1","question":"<p>(L2 [D]) Почему optimizer недооценил размер intermediate result?</p>\n","answer":"<p><strong>Ответ:</strong> Term/epoch различает поколения authority; fencing проверяется самим принимающим ресурсом, отвергающим старого владельца. Lease timeout на клиенте недостаточен, если остановленный процесс возобновился и всё ещё способен писать. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":676},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:38a502f34ed2bdd5:1","question":"<p>(L2 [D]) Почему spill to disk случился, хотя cost model ожидала fit in memory?</p>\n","answer":"<p><strong>Ответ:</strong> Hash/sort spill переносит промежуточные данные на временный storage при недостаточном memory budget. Увеличение per-operator memory умножается на operators/workers/queries и может вызвать OOM; сначала проверить cardinality и concurrency. Planner search может строиться снизу вверх dynamic programming либо сверху вниз через memo/rules и physical requirements. Search space grows combinatorially, поэтому pruning/budgets/heuristics обязательны; semantic equivalence проверяется отдельно от cost. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":683},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:990c2114822f957d:1","question":"<p>(L3 [T]) Как устроены реальные cost models в PostgreSQL/коммерческих СУБД?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":690},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e6d50912111d0eef:1","question":"<p>(L3 [T]) Почему cost model завязана на hardware assumptions?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":697},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e5d74a23341b868c:1","question":"<p>(L3 [T]) Как CPU cache, branch prediction и vectorization влияют на современный CBO?</p>\n","answer":"<p><strong>Ответ:</strong> Vectorized batches уменьшают per-row overhead и помогают SIMD, но memory bandwidth/gather/variable-length types могут ограничить выигрыш. Нужны feature detection, безопасный tail и scalar oracle; наличие vector instructions само не доказывает ускорение.</p>\n<p><strong>Источник:</strong> <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Cost-based optimizer","line":704},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:14f7fa147959b438:1","question":"<p>(L3 [T]) Почему one-size-fits-all cost constants редко работают?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":711},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:09cf78109200c245:1","question":"<p>(L3 [T]) Как adaptive / runtime re-optimization соотносится с классическим CBO?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":718},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:50f409fe8f610d15:1","question":"<p>(L3 [T]) Как optimizer учитывает partition pruning и data locality?</p>\n","answer":"<p><strong>Ответ:</strong> Pushdown/pruning уменьшают работу до materialization/shipping, только если преобразование сохраняет semantics. Metadata min/max позволяют пропустить блок лишь при доказанном отсутствии совпадений, включая NULL/collation правила. Locality сокращает RTT/shipping, но должна учитывать freshness, quorum и fault domains. Ближайший node не всегда eligible; приближение одного leader может увеличить remote reads/влияние на других tenants.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/deployment-stamp\">Azure Architecture: Deployment stamps</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"🔹 Cost-based optimizer","line":725},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:da3c66b874f0121e:1","question":"<p>(L3 [T]) Как CBO учитывает parallelism?</p>\n","answer":"<p><strong>Ответ:</strong> Parallelism делит работу, но добавляет exchange, coordination и memory per worker. Skew/serial stages/bandwidth ограничивают speedup; увеличение workers может ухудшить общую multitenant capacity и p99.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🔹 Cost-based optimizer","line":732},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:09ff8c80c9764cb2:1","question":"<p>(L3 [T]) Почему misestimated cardinality часто доминирует над ошибками в cost constants?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cost-based optimizer","line":739},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cd31a4c46cf9b5b2:1","question":"<p>(L3 [T]) Как optimizer должен учитывать buffer pool/page cache effects?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Cost-based optimizer","line":746},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ef1748bfa3742b40:1","question":"<p>(L3 [T]) Почему CBO — это одновременно статистика, алгоритмы и engineering compromise?</p>\n","answer":"<p><strong>Ответ:</strong> Cost model оценивает CPU/I/O/memory/network по cardinality и доступным paths, а не предсказывает точное wall-clock время. Ошибка оценок промежуточных наборов особенно опасна для join order, hash memory и distributed shuffle.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":753},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:0e3ee23ce9a91964:1","question":"<p>(L3 [P]) Реализовать calibration benchmark для cost constants</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать dataset/seed, целевой profile операций, одинаковую durability и correctness oracle. Сравнивать cold/warm, concurrency/QD и steady-state maintenance, измеряя finished ops/bytes, p50/p99 и errors; менять один исследуемый параметр и исключить setup из таймера.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"🔹 Cost-based optimizer","line":760},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:00e96229f32eb024:1","question":"<p>(L3 [P]) Реализовать skew-aware histogram</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные. Равномерное число keys/bytes не гарантирует равномерный traffic или join work. Измерять heat по ключам/partitions и стоимость операций; hot single key отличается от множества неравномерно распределённых keys. Задать затраты scan, lookup, sort/join и shipping с явными единицами, оценки selectivity и cumulative rows. Калибровать на измерениях, проверять orders-of-magnitude ошибки и не подменять correctness стоимостным эвристическим правилом.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":767},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:3d0ec8db773c7b7d:1","question":"<p>(L3 [P]) Реализовать cost model с учётом cache hit ratio</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":774},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:32fae4b12dc5f62b:1","question":"<p>(L3 [P]) Реализовать optimizer trace: chosen cost vs actual runtime</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":781},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fb32a3fb535104b1:1","question":"<p>(L3 [P]) Реализовать re-optimization trigger при large cardinality misprediction</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения. Задать затраты scan, lookup, sort/join и shipping с явными единицами, оценки selectivity и cumulative rows. Калибровать на измерениях, проверять orders-of-magnitude ошибки и не подменять correctness стоимостным эвристическим правилом.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":788},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:20103f54539d4272:1","question":"<p>(L3 [D]) Как доказать, что корень проблемы в cardinality estimation, а не в executor?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":795},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:6dd4458a2eb1da76:1","question":"<p>(L3 [D]) Почему cost model работает на тестах и ломается на production workload?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":802},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:722524d970fcf2a2:1","question":"<p>(L3 [D]) Как расследовать parameter-sensitive regression?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":809},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:15821fc7e92fbe88:1","question":"<p>(L3 [D]) Почему оптимизатор систематически недооценивает joins на correlated columns?</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные. Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":816},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d1cd8b075fa33f91:1","question":"<p>(L3 [D]) Как понять, что пора менять cost model, а не “тюнить запросы вручную”?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить estimate/actual cardinality на каждом node, statistics freshness, skew/correlations и cached parameterized plan. Ошибка верхнего operator часто является следствием нижнего неверного estimate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":823},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7aa04fc66cc989c4:1","question":"<p>(L4 [S]) Когда для своей БД оправдан полноценный CBO?</p>\n","answer":"<p><strong>Ответ:</strong> Расширять модель только под наблюдаемые workload regressions; учитывать uncertainty и resource budgets. Точный micro-cost не компенсирует ошибку cardinality на несколько порядков, поэтому сначала улучшать statistics/selectivity.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":830},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fd3b9524432c9810:1","question":"<p>(L4 [S]) Как эволюционировать optimizer от rule-based к cost-based?</p>\n","answer":"<p><strong>Ответ:</strong> Расширять модель только под наблюдаемые workload regressions; учитывать uncertainty и resource budgets. Точный micro-cost не компенсирует ошибку cardinality на несколько порядков, поэтому сначала улучшать statistics/selectivity.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":837},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d29acc55039773e2:1","question":"<p>(L4 [S]) Как строить cost model, не привязанную намертво к одной машине?</p>\n","answer":"<p><strong>Ответ:</strong> Расширять модель только под наблюдаемые workload regressions; учитывать uncertainty и resource budgets. Точный micro-cost не компенсирует ошибку cardinality на несколько порядков, поэтому сначала улучшать statistics/selectivity.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":844},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4b9c741969f06df5:1","question":"<p>(L4 [S]) Как проектировать feedback loop actual runtime → optimizer stats?</p>\n","answer":"<p><strong>Ответ:</strong> Расширять модель только под наблюдаемые workload regressions; учитывать uncertainty и resource budgets. Точный micro-cost не компенсирует ошибку cardinality на несколько порядков, поэтому сначала улучшать statistics/selectivity.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":851},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d5c6deb471e36e47:1","question":"<p>(L4 [S]) Как объяснять команде, что optimizer не может быть “всегда прав” по определению?</p>\n","answer":"<p><strong>Ответ:</strong> Расширять модель только под наблюдаемые workload regressions; учитывать uncertainty и resource budgets. Точный micro-cost не компенсирует ошибку cardinality на несколько порядков, поэтому сначала улучшать statistics/selectivity.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cost-based optimizer","line":858},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:49558d13faebbb52:1","question":"<p>(L1 [T]) Что такое execution plan?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":869},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5191d104b34f41ef:1","question":"<p>(L1 [T]) Чем execution plan отличается от исходного SQL?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":876},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:877994b2288c10fa:1","question":"<p>(L1 [T]) Что обычно видно в execution plan: scan, filter, join, sort, aggregate?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":883},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:abe5b5c944bf3c55:1","question":"<p>(L1 [T]) Почему execution plan полезен при performance debugging?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":890},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:516ee67b83b1a95d:1","question":"<p>(L1 [T]) Что такое estimated plan и actual plan?</p>\n","answer":"<p><strong>Ответ:</strong> Estimated plan показывает оценки без выполнения, actual добавляет наблюдённые rows/loops/timing/buffers после исполнения. EXPLAIN ANALYZE реально выполняет запрос, в том числе изменяющий, и добавляет measurement overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":897},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:3841600bbf94099d:1","question":"<p>(L1 [T]) Почему row estimate и actual rows — критично важные поля?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":904},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:30924c27713de1c9:1","question":"<p>(L1 [T]) Что означает seq scan в плане?</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":911},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5b7d4c1c7addc818:1","question":"<p>(L1 [T]) Что означает index scan в плане?</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":918},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:806807e542912a05:1","question":"<p>(L1 [T]) Что означает hash join / nested loop / merge join?</p>\n","answer":"<p><strong>Ответ:</strong> Hash join строит hash table одной стороны и probe другой; выгоден для соответствующих equality predicates. Build cardinality/width и memory limit определяют spill, skew может создать перегруженный partition. Nested loop выполняет inner path для каждой outer row, поэтому rows×loops важны. При малом outer и indexed inner он эффективен, при ошибке оценки превращается в огромное число probes.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":925},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:04ddb1d2a2285924:1","question":"<p>(L1 [T]) Почему plan tree читается снизу вверх?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":932},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d78c7514a71b9cbc:1","question":"<p>(L1 [P]) Реализовать pretty-printer execution plan tree</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":939},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c24799cd50e6b948:1","question":"<p>(L1 [P]) Реализовать instrumentation: actual rows/time per node</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":946},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:dbf34952df207cb8:1","question":"<p>(L1 [P]) Реализовать explain output для своего mini-engine</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":953},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:90d5ad9bbb41f2cb:1","question":"<p>(L1 [P]) Реализовать estimated vs actual counters</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":960},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8a5dbc6bfdf932f5:1","question":"<p>(L1 [P]) Реализовать tree walker для анализа plan nodes</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs. Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":967},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2c8032a89fa21ddd:1","question":"<p>(L2 [T]) Почему actual plan важнее estimated plan при расследовании?</p>\n","answer":"<p><strong>Ответ:</strong> Estimated plan показывает оценки без выполнения, actual добавляет наблюдённые rows/loops/timing/buffers после исполнения. EXPLAIN ANALYZE реально выполняет запрос, в том числе изменяющий, и добавляет measurement overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":974},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f3386e47cd5e7de0:1","question":"<p>(L2 [T]) Что такое startup time и total time node-а?</p>\n","answer":"<p><strong>Ответ:</strong> Startup time node — время до первой строки, total — до завершения выдачи в принятом explain формате. При loops/parallel execution метрики требуют правильного масштабирования и inclusive/exclusive понимания, а не простого суммирования всех nodes.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":981},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:be02485c70182af9:1","question":"<p>(L2 [T]) Почему loops count важен в nested loop-heavy plans?</p>\n","answer":"<p><strong>Ответ:</strong> Nested loop выполняет inner path для каждой outer row, поэтому rows×loops важны. При малом outer и indexed inner он эффективен, при ошибке оценки превращается в огромное число probes.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":988},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4b0eb012a3f8d5bf:1","question":"<p>(L2 [T]) Как plan показывает, где происходят sorts и materialization?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":995},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d8e35942f77af2cc:1","question":"<p>(L2 [T]) Почему plan node может быть cheap, но multiplier effect делает его дорогим?</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":1002},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:192b4a3aa9a280f5:1","question":"<p>(L2 [T]) Что такое plan instability?</p>\n","answer":"<p><strong>Ответ:</strong> Plan instability — изменение выбранного физического плана при изменении statistics/parameters/schema/configuration. Это не всегда regression; сравнить actual latency/output и rows estimates по репрезентативным parameter classes.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":1009},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cffbb61c502fd875:1","question":"<p>(L2 [T]) Почему два похожих запроса могут иметь radically different plans?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1016},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bb0b87ba40f104e1:1","question":"<p>(L2 [T]) Что такое plan cache?</p>\n","answer":"<p><strong>Ответ:</strong> Один cached/generic plan может быть неудачен для skewed parameter values. Сравнить реальные bind values, generic/custom plan, statistics и actual rows; отключение cache глобально может добавить заметный planning overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Execution plans","line":1023},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:47b691a9cac5373c:1","question":"<p>(L2 [T]) Почему cached plan может стать неактуальным?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1030},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d0e8aedfa612b044:1","question":"<p>(L2 [T]) Почему execution plan — это interface между optimizer и executor?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1037},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1b7e1a947313e8dc:1","question":"<p>(L2 [P]) Реализовать collection actual timing per operator</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs. Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1044},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fef0f305a99bf301:1","question":"<p>(L2 [P]) Реализовать loops-aware plan instrumentation</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1051},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:91c47ef4e617ce70:1","question":"<p>(L2 [P]) Реализовать detect large estimate error in explain output</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1058},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2deff1e6d42e2516:1","question":"<p>(L2 [P]) Реализовать plan diff tool для двух execution plans</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1065},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1ed1a9244fe934ff:1","question":"<p>(L2 [P]) Реализовать simple plan cache с invalidation по statistics change</p>\n","answer":"<p><strong>Ответ:</strong> Сравнивать canonical data по стабильным ranges и согласованным versions, count дополнить hashes/values/business invariants. Checksum покрывает identity/length/version; mismatch сохраняется с provenance и чинится из доверенного source, а не молча игнорируется.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/checksums.html\">PostgreSQL: Data checksums</a>; <a href=\"https://www.postgresql.org/docs/current/logical-replication.html\">PostgreSQL: Logical replication</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1072},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:619cfe04fe52431b:1","question":"<p>(L2 [D]) Почему plan выглядит “нормально”, а запрос медленный?</p>\n","answer":"<p><strong>Ответ:</strong> Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1079},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1c7b026393d7b004:1","question":"<p>(L2 [D]) Почему actual rows на два порядка больше estimate?</p>\n","answer":"<p><strong>Ответ:</strong> Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1086},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:06002f2c5749856f:1","question":"<p>(L2 [D]) Почему nested loop неожиданно вызвал миллионы index lookups?</p>\n","answer":"<p><strong>Ответ:</strong> Nested loop выполняет inner path для каждой outer row, поэтому rows×loops важны. При малом outer и indexed inner он эффективен, при ошибке оценки превращается в огромное число probes. Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1093},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bff194d74e1a4d16:1","question":"<p>(L2 [D]) Почему sort node spill-ится на диск?</p>\n","answer":"<p><strong>Ответ:</strong> Hash/sort spill переносит промежуточные данные на временный storage при недостаточном memory budget. Увеличение per-operator memory умножается на operators/workers/queries и может вызвать OOM; сначала проверить cardinality и concurrency. Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1100},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4f22979f9a444665:1","question":"<p>(L2 [D]) Почему planner cache держит устаревший плохой plan?</p>\n","answer":"<p><strong>Ответ:</strong> Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1107},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b6ef7599ddd0afe5:1","question":"<p>(L3 [T]) Как устроено instrumentation plan nodes с минимальным overhead?</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":1114},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:dad98048cbcb4d87:1","question":"<p>(L3 [T]) Как actual execution plans помогают тюнить optimizer?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1121},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:007a9ce67bdcf553:1","question":"<p>(L3 [T]) Как parallel execution отражается в execution plan?</p>\n","answer":"<p><strong>Ответ:</strong> Parallelism делит работу, но добавляет exchange, coordination и memory per worker. Skew/serial stages/bandwidth ограничивают speedup; увеличение workers может ухудшить общую multitenant capacity и p99.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🔹 Execution plans","line":1128},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:917c630ba1aecb8d:1","question":"<p>(L3 [T]) Как visibility checks, rechecks и heap fetches отражаются в плане?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1135},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:805914f46c7fde61:1","question":"<p>(L3 [T]) Почему explain/analyze сам может менять timing behavior?</p>\n","answer":"<p><strong>Ответ:</strong> Устаревшие/недостаточные statistics искажает rows/selectivity, меняя join/index decisions. ANALYZE полезен, но sampling/skew/correlations остаются; сравнить estimates и actual до и после, не форсировать план вслепую.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":1142},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:68884b9778eb4a9a:1","question":"<p>(L3 [T]) Как flamegraphs/perf traces соотносятся с plan nodes?</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":1149},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:abc3421dd6a7080f:1","question":"<p>(L3 [T]) Как materialization и buffering влияют на shape плана?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1156},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:68b82195cc6536ae:1","question":"<p>(L3 [T]) Как executor pipeline breakers отражаются в плане?</p>\n","answer":"<p><strong>Ответ:</strong> Execution plan задаёт физические scan/join/aggregate/sort operators и их потоки данных. Actual rows, loops, memory/spill и критический путь объясняют работу; суммировать inclusive node times как независимые затраты нельзя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1163},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f97244c1d493aab9:1","question":"<p>(L3 [T]) Почему production-safe observability execution plans сложна?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны metrics и traces по shard/tenant/region/stage с ограниченной cardinality, а не только общий health. Разделять queue wait, service, I/O, replication и retries, сохранять operation/epoch context без утечки payload/секретов.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a></p>\n","group":"🔹 Execution plans","line":1170},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:35680c70f981802d:1","question":"<p>(L3 [T]) Как строить mapping “SQL fragment → plan node → CPU/IO cost”?</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Execution plans","line":1177},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:081ac21c08867303:1","question":"<p>(L3 [P]) Реализовать lightweight sampling profiler по plan nodes</p>\n","answer":"<p><strong>Ответ:</strong> Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs. Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1184},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:274bc944261bba8a:1","question":"<p>(L3 [P]) Реализовать actual vs estimated cardinality heatmap</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения. Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1191},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fba0dc1c1606beac:1","question":"<p>(L3 [P]) Реализовать trace executor events с привязкой к plan tree</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1198},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e89ff5f4bba87d4c:1","question":"<p>(L3 [P]) Реализовать spill diagnostics для sort/hash nodes</p>\n","answer":"<p><strong>Ответ:</strong> Hash/sort spill переносит промежуточные данные на временный storage при недостаточном memory budget. Увеличение per-operator memory умножается на operators/workers/queries и может вызвать OOM; сначала проверить cardinality и concurrency. Реализовать pipeline operators над batches/iterators, явный row schema и NULL semantics. Blocking stages имеют memory limit/spill, cancellation освобождает state; сравнить output с reference interpreter на edge cases.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1205},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:872623dfa0290666:1","question":"<p>(L3 [P]) Реализовать plan regression detector по сохранённым explain snapshots</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать engine/volume snapshot boundary, manifest/base dependencies и reference counts/retention. CoW сохраняет old blocks до release, partial snapshot не публикуется; проверить multi-volume consistency, base loss и restore/restart.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/backup.html\">PostgreSQL: Backup and restore</a>; <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1212},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c2c9b95d363f2c65:1","question":"<p>(L3 [D]) Как доказать, что плохой runtime идёт из-за executor bottleneck внутри “правильного” плана?</p>\n","answer":"<p><strong>Ответ:</strong> Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1219},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:9803b3d63f234878:1","question":"<p>(L3 [D]) Почему explain analyze показывает одно, а production профилирование другое?</p>\n","answer":"<p><strong>Ответ:</strong> Устаревшие/недостаточные statistics искажает rows/selectivity, меняя join/index decisions. ANALYZE полезен, но sampling/skew/correlations остаются; сравнить estimates и actual до и после, не форсировать план вслепую. Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1226},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8eba30d721530681:1","question":"<p>(L3 [D]) Как расследовать plan regression, проявляющуюся только на одном tenant-е?</p>\n","answer":"<p><strong>Ответ:</strong> Tenant identity должна входить в routing/keys/проверки доступа и quotas. Изоляция CPU/I/O/memory/queues нужна помимо логического ACL; global averages скрывают noisy-neighbor нарушение SLO отдельных tenants. Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html\">OWASP: Authorization</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1233},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fcdfb99422b65f5d:1","question":"<p>(L3 [D]) Почему actual loops count explodes на correlated subquery?</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные. Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1240},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:0289578866d3874d:1","question":"<p>(L3 [D]) Как найти один node, который формально cheap, но ломает p99 из-за cache miss/spill?</p>\n","answer":"<p><strong>Ответ:</strong> Hash/sort spill переносит промежуточные данные на временный storage при недостаточном memory budget. Увеличение per-operator memory умножается на operators/workers/queries и может вызвать OOM; сначала проверить cardinality и concurrency. Tail определяется очередями, редкими stalls и fan-out: хороший p50 не исключает плохой p99. Сопоставить временную линию с maintenance, topology changes и resource saturation; retry/hedging добавляют нагрузку и требуют бюджета. Разобрать actual rows×loops, filtered rows, sort/hash spill и buffer/I/O. Найти доминирующую стадию и её причину: plan, resource saturation, skew или data growth; сравнить workload до/после regression.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://research.google/pubs/the-tail-at-scale/\">Dean, Barroso: The Tail at Scale</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1247},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:9d3d6e4334335d09:1","question":"<p>(L4 [S]) Как строить explain/trace tooling для собственной СУБД?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать iterator/vectorized/fused execution под типы и latency/throughput, сохраняя observability. Ограничить intermediate memory и parallel fan-out; faster operator не улучшит запрос, если bottleneck в remote I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1254},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cfbefbc5a7ff3f07:1","question":"<p>(L4 [S]) Какие execution metrics нужно собирать с первого дня?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать iterator/vectorized/fused execution под типы и latency/throughput, сохраняя observability. Ограничить intermediate memory и parallel fan-out; faster operator не улучшит запрос, если bottleneck в remote I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1261},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c03f7d41dda14892:1","question":"<p>(L4 [S]) Как балансировать информативность explain output и overhead instrumentation?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать iterator/vectorized/fused execution под типы и latency/throughput, сохраняя observability. Ограничить intermediate memory и parallel fan-out; faster operator не улучшит запрос, если bottleneck в remote I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1268},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:59eca2138fa7eb34:1","question":"<p>(L4 [S]) Как включить plan analysis в регулярный perf review команды?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать iterator/vectorized/fused execution под типы и latency/throughput, сохраняя observability. Ограничить intermediate memory и parallel fan-out; faster operator не улучшит запрос, если bottleneck в remote I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1275},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ee96cae11c8fea33:1","question":"<p>(L4 [S]) Как объяснять разработчикам, что execution plan — это главный источник правды о запросе, а не догадки по SQL?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать iterator/vectorized/fused execution под типы и latency/throughput, сохраняя observability. Ограничить intermediate memory и parallel fan-out; faster operator не улучшит запрос, если bottleneck в remote I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://arrow.apache.org/docs/format/Columnar.html\">Apache Arrow: Columnar format</a></p>\n","group":"🔹 Execution plans","line":1282},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a77ccb69947abfb1:1","question":"<p>(L1 [T]) Что такое index selection в контексте optimizer-а?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1293},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fd01ebb736ea2a1f:1","question":"<p>(L1 [T]) Почему наличие индекса ещё не означает, что он будет использован?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1300},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:74eb5711774d8642:1","question":"<p>(L1 [T]) Что такое selectivity индекса?</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1307},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8b845b51b996b2d2:1","question":"<p>(L1 [T]) Почему low-selectivity index часто бесполезен?</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1314},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1c0efefea6e5b39e:1","question":"<p>(L1 [T]) Что такое composite index?</p>\n","answer":"<p><strong>Ответ:</strong> Composite index сортирует tuple ключей лексикографически по объявленному comparator. Leading equality prefix и следующий range дают полезные bounds; suffix-only доступ/skip-scan зависят от engine, а payload INCLUDE не является частью sort key.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1321},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:6b358c03242c395c:1","question":"<p>(L1 [T]) Почему порядок колонок в composite index важен?</p>\n","answer":"<p><strong>Ответ:</strong> Composite index сортирует tuple ключей лексикографически по объявленному comparator. Leading equality prefix и следующий range дают полезные bounds; suffix-only доступ/skip-scan зависят от engine, а payload INCLUDE не является частью sort key.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1328},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8ed77339acfea100:1","question":"<p>(L1 [T]) Что такое covering index?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс, содержащий все поля, нужные query predicates/order/projection. Может избежать table fetch, но не всех visibility checks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1335},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8311ac65437957e6:1","question":"<p>(L1 [T]) Почему index lookup может быть дороже seq scan?</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1342},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2c7a17d6e699c48f:1","question":"<p>(L1 [T]) Что такое index-only scan?</p>\n","answer":"<p><strong>Ответ:</strong> Чтение результата из index при доступных полях и доказанной видимости. В PostgreSQL visibility map может потребовать heap fallback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1349},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4e6302b304392339:1","question":"<p>(L1 [T]) Почему secondary index может требовать table/heap lookup?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1356},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8e090a34958dd3c1:1","question":"<p>(L1 [P]) Реализовать выбор между seq scan и single-column index</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования. Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1363},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:dce3b301346b5549:1","question":"<p>(L1 [P]) Реализовать поддержку composite index selection</p>\n","answer":"<p><strong>Ответ:</strong> Tuple comparator задаёт lexicographic key order и NULL/collation rules, bounds выражают допустимый prefix/range. Search и updates используют тот же encoding, string-prefix upper bound не всегда простое увеличение byte.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1370},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e87bd682221c3a52:1","question":"<p>(L1 [P]) Реализовать простую оценку selectivity</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями. Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1377},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d0442b8442bffa38:1","question":"<p>(L1 [P]) Реализовать covering-index fast path</p>\n","answer":"<p><strong>Ответ:</strong> Стабильно кодировать key/tokens, выбирать owner и distinct fault-domain replicas по общей versioned membership. Симулировать join/leave/weights, считать moved keys и requests/bytes skew; перенос данных/cutover не подменяется пересчётом hash.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1384},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:28ea5079cccc72c8:1","question":"<p>(L1 [P]) Реализовать heuristic “не использовать индекс при высокой selectivity”</p>\n","answer":"<p><strong>Ответ:</strong> Selectivity — доля строк, проходящих predicate. Очень большая доля может сделать full scan дешевле random lookups; estimates нужно сверять с actual и учитывать correlations между полями. Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1391},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bb43739bde8afcd2:1","question":"<p>(L2 [T]) Почему optimizer должен учитывать clustering factor / locality?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1398},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:93131449f3d9e319:1","question":"<p>(L2 [T]) Почему range predicate лучше подходит B-Tree, чем hash index?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1405},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8eae4ff22c3fc6d1:1","question":"<p>(L2 [T]) Почему composite index <code>(a, b)</code> не всегда помогает по <code>WHERE b = ?</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Composite index сортирует tuple ключей лексикографически по объявленному comparator. Leading equality prefix и следующий range дают полезные bounds; suffix-only доступ/skip-scan зависят от engine, а payload INCLUDE не является частью sort key.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1412},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:81bf4759e17865b1:1","question":"<p>(L2 [T]) Что такое prefix matching в composite index?</p>\n","answer":"<p><strong>Ответ:</strong> Composite index сортирует tuple ключей лексикографически по объявленному comparator. Leading equality prefix и следующий range дают полезные bounds; suffix-only доступ/skip-scan зависят от engine, а payload INCLUDE не является частью sort key.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1419},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4ab2702fc9411110:1","question":"<p>(L2 [T]) Почему фильтр, сортировка и join могут конкурировать за “лучший” индекс?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1426},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:45257e1f4e6f69c5:1","question":"<p>(L2 [T]) Что такое skip scan / bitmap scan и зачем они нужны?</p>\n","answer":"<p><strong>Ответ:</strong> Skip scan выполняет серию probes по подходящим leading-key значениям при допустимом distribution, bitmap scan сначала собирает row/page candidates и затем читает их группами. Доступность/выгодность зависят от engine/version и selectivity.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1433},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:71f6f731613c3961:1","question":"<p>(L2 [T]) Почему optimizer иногда выбирает несколько индексов, а не один?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1440},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5cbb2317cd1a916f:1","question":"<p>(L2 [T]) Как MVCC visibility влияет на реальную стоимость index-only scan?</p>\n","answer":"<p><strong>Ответ:</strong> В PostgreSQL index-only scan избегает heap fetch, когда visibility map подтверждает all-visible page. Частые writes/недостаточный VACUUM уменьшают эффект даже при полном covering index.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/routine-vacuuming.html\">PostgreSQL: Routine vacuuming</a></p>\n","group":"🔹 Index selection","line":1447},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:720a6920cb0fa9a7:1","question":"<p>(L2 [T]) Почему stale statistics ломают index selection?</p>\n","answer":"<p><strong>Ответ:</strong> Устаревшие/недостаточные statistics искажает rows/selectivity, меняя join/index decisions. ANALYZE полезен, но sampling/skew/correlations остаются; сравнить estimates и actual до и после, не форсировать план вслепую.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1454},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:45572fe9a9b9f9f4:1","question":"<p>(L2 [T]) Почему over-indexing ухудшает writes и иногда даже reads?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1461},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bbc2e93f7a2c942f:1","question":"<p>(L2 [P]) Реализовать composite-index prefix rules</p>\n","answer":"<p><strong>Ответ:</strong> Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1468},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:aed7aa856a644f31:1","question":"<p>(L2 [P]) Реализовать bitmap index merge (упрощённо)</p>\n","answer":"<p><strong>Ответ:</strong> Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1475},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7a1f59643e7e0405:1","question":"<p>(L2 [P]) Реализовать cost model для covering vs non-covering index</p>\n","answer":"<p><strong>Ответ:</strong> Index entry включает search key/locator и нужный payload; query проверяет coverage, snapshot visibility и residual predicates. Если видимость/поле не доказаны, fetch row; test compare с table scan на concurrent update/delete.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1482},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:9a8ee35de068e645:1","question":"<p>(L2 [P]) Реализовать выбор индекса под filter + order by</p>\n","answer":"<p><strong>Ответ:</strong> Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1489},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:221ecdef8e4ab570:1","question":"<p>(L2 [P]) Реализовать advisor, предлагающий индекс по observed queries</p>\n","answer":"<p><strong>Ответ:</strong> Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1496},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a13a0dedce046e6f:1","question":"<p>(L2 [D]) Почему optimizer не использует “очевидный” индекс?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1503},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f635adfd67dacbaa:1","question":"<p>(L2 [D]) Почему после создания индекса запрос стал медленнее?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1510},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e0bcca36bbe42b98:1","question":"<p>(L2 [D]) Почему composite index почти не помог?</p>\n","answer":"<p><strong>Ответ:</strong> Composite index сортирует tuple ключей лексикографически по объявленному comparator. Leading equality prefix и следующий range дают полезные bounds; suffix-only доступ/skip-scan зависят от engine, а payload INCLUDE не является частью sort key. Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1517},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2adce2a8398e7cd6:1","question":"<p>(L2 [D]) Почему index-only scan всё равно ходит в heap/table?</p>\n","answer":"<p><strong>Ответ:</strong> В PostgreSQL index-only scan избегает heap fetch, когда visibility map подтверждает all-visible page. Частые writes/недостаточный VACUUM уменьшают эффект даже при полном covering index. Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/routine-vacuuming.html\">PostgreSQL: Routine vacuuming</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1524},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:099324302b6f9750:1","question":"<p>(L2 [D]) Почему low-cardinality predicate создаёт плохой index plan?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения. Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1531},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:216c34c604303529:1","question":"<p>(L3 [T]) Как optimizer выбирает между multiple usable indexes?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1538},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c4f896d6d32c956e:1","question":"<p>(L3 [T]) Как column correlation влияет на index usefulness?</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Index selection","line":1545},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d2f7364cd8d5de35:1","question":"<p>(L3 [T]) Как cache residency индекса должна учитываться в выборе?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1552},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7b94ef1219c90831:1","question":"<p>(L3 [T]) Как partial indexes и filtered indexes меняют index selection?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1559},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8fd5578fbe5986e9:1","question":"<p>(L3 [T]) Как planner учитывает maintenance cost индекса косвенно через workload mix?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1566},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4cf4b55ed1756cd6:1","question":"<p>(L3 [T]) Как индекс может одновременно помогать WHERE, ORDER BY и JOIN?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1573},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b33cb6331e35485b:1","question":"<p>(L3 [T]) Как partitioned tables усложняют index selection?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1580},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:47218db5ffbb77d0:1","question":"<p>(L3 [T]) Как global vs local indexes влияют на distributed cost?</p>\n","answer":"<p><strong>Ответ:</strong> Глобальная uniqueness/index update охватывает несколько владельцев и требует координации или специального allocation протокола. Local UNIQUE на shards не доказывает global invariant; async global projection может временно отставать.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a></p>\n","group":"🔹 Index selection","line":1587},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bd8b2309d3d79389:1","question":"<p>(L3 [T]) Почему index advisor без workload-awareness почти бесполезен?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1594},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5454a648cd630b02:1","question":"<p>(L3 [T]) Как строить explainability для решений optimizer-а по выбору индекса?</p>\n","answer":"<p><strong>Ответ:</strong> Индекс полезен при соответствии predicate/order/join и достаточной selectivity; большая доля строк может читаться быстрее sequential scan. Composite порядок, expressions, collation, NULL и covering влияют на применимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1601},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:862e03c0f68545fc:1","question":"<p>(L3 [P]) Реализовать multi-index candidate scoring</p>\n","answer":"<p><strong>Ответ:</strong> В одной atomic write boundary менять row и old/new index entries, учитывать duplicates/NULL/constraints. Старые snapshot references удерживать до GC; test rollback/error после каждого index change и lookup equivalence со scan.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1608},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a9f5b620f25aca08:1","question":"<p>(L3 [P]) Реализовать partial-index eligibility check</p>\n","answer":"<p><strong>Ответ:</strong> Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1615},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a262974d2beee245:1","question":"<p>(L3 [P]) Реализовать cache-aware index cost estimation</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1622},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:3548f2e4a5386743:1","question":"<p>(L3 [P]) Реализовать index usage telemetry и unused-index detector</p>\n","answer":"<p><strong>Ответ:</strong> Нужны metrics и traces по shard/tenant/region/stage с ограниченной cardinality, а не только общий health. Разделять queue wait, service, I/O, replication и retries, сохранять operation/epoch context без утечки payload/секретов. Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1629},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:20a3c817bef48729:1","question":"<p>(L3 [P]) Реализовать what-if optimizer для виртуальных индексов</p>\n","answer":"<p><strong>Ответ:</strong> Перечислить semantically допустимые scan/join/order alternatives, оценить rows/selectivity/CPU/IO/memory и выбрать minimum cost. Сравнить output с reference и estimates с actual, включить skew/correlation/cold-warm и разные bind values.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1636},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5c971f6824dfd585:1","question":"<p>(L3 [D]) Как доказать, что причина плохого плана — correlation/skew, а не отсутствие индекса?</p>\n","answer":"<p><strong>Ответ:</strong> Статистика описывает распределения/частые значения и иногда зависимости столбцов. Оценка независимости predicates ошибается при correlation; ANALYZE/extended statistics помогают, но не предсказывают все меняющиеся данные. Равномерное число keys/bytes не гарантирует равномерный traffic или join work. Измерять heat по ключам/partitions и стоимость операций; hot single key отличается от множества неравномерно распределённых keys. Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🔹 Index selection","line":1643},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:36bf215003ad0d25:1","question":"<p>(L3 [D]) Почему index advisor рекомендует индекс, который на деле вреден?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1650},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:129c2c6e1b56c35b:1","question":"<p>(L3 [D]) Почему один tenant постоянно получает другой index plan?</p>\n","answer":"<p><strong>Ответ:</strong> Tenant identity должна входить в routing/keys/проверки доступа и quotas. Изоляция CPU/I/O/memory/queues нужна помимо логического ACL; global averages скрывают noisy-neighbor нарушение SLO отдельных tenants. Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html\">OWASP: Authorization</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1657},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b4a7ec53987754ad:1","question":"<p>(L3 [D]) Как расследовать случай, когда индекс ускоряет p50, но ухудшает p99?</p>\n","answer":"<p><strong>Ответ:</strong> Tail определяется очередями, редкими stalls и fan-out: хороший p50 не исключает плохой p99. Сопоставить временную линию с maintenance, topology changes и resource saturation; retry/hedging добавляют нагрузку и требуют бюджета. Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/the-tail-at-scale/\">Dean, Barroso: The Tail at Scale</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1664},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e550476bafd4f9dd:1","question":"<p>(L3 [D]) Почему cache residency индекса изменила поведение optimizer-а после рестарта?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить casts/functions, leading columns, statistics и estimated/actual selectivity. Отдельно измерить index probes, heap fetch и cache state; отсутствие Index Scan не означает ошибку optimizer.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1671},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4846ff4687d5a28e:1","question":"<p>(L4 [S]) Как проектировать indexing strategy для нового продукта, а не для одного запроса?</p>\n","answer":"<p><strong>Ответ:</strong> Поддерживать минимальный полезный набор под реальные queries/constraints. Не создавать index на каждый столбец; удаление/изменение и online build требуют impact analysis, capacity и rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1678},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:0a633d613d5af07c:1","question":"<p>(L4 [S]) Когда лучше добавить индекс, а когда переписать access pattern?</p>\n","answer":"<p><strong>Ответ:</strong> Поддерживать минимальный полезный набор под реальные queries/constraints. Не создавать index на каждый столбец; удаление/изменение и online build требуют impact analysis, capacity и rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1685},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d233c572d4b222a6:1","question":"<p>(L4 [S]) Как балансировать read gains и write amplification от индексов?</p>\n","answer":"<p><strong>Ответ:</strong> Поддерживать минимальный полезный набор под реальные queries/constraints. Не создавать index на каждый столбец; удаление/изменение и online build требуют impact analysis, capacity и rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1692},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:62b90ba5803ad128:1","question":"<p>(L4 [S]) Как строить индексную политику для multi-tenant системы?</p>\n","answer":"<p><strong>Ответ:</strong> Tenant identity должна входить в routing/keys/проверки доступа и quotas. Изоляция CPU/I/O/memory/queues нужна помимо логического ACL; global averages скрывают noisy-neighbor нарушение SLO отдельных tenants.</p>\n<p><strong>Рекомендация:</strong> Поддерживать минимальный полезный набор под реальные queries/constraints. Не создавать index на каждый столбец; удаление/изменение и online build требуют impact analysis, capacity и rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html\">OWASP: Authorization</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1699},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:11df6b970cb5adfa:1","question":"<p>(L4 [S]) Как объяснять команде, что индекс — это trade-off, а не бесплатное ускорение?</p>\n","answer":"<p><strong>Ответ:</strong> Поддерживать минимальный полезный набор под реальные queries/constraints. Не создавать index на каждый столбец; удаление/изменение и online build требуют impact analysis, capacity и rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Index selection","line":1708},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c335078ced363de8:1","question":"<p>(L1 [T]) Что такое buffer pool?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Пример:</strong> Frame с pin_count=1 не является допустимым eviction victim, даже если давно не было hit.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1719},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fefd9362fba9c8b6:1","question":"<p>(L1 [T]) Чем buffer pool БД отличается от page cache ОС?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1728},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:11065abe94b14abd:1","question":"<p>(L1 [T]) Зачем БД держит собственный cache страниц?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1735},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1b9b07d08c860894:1","question":"<p>(L1 [T]) Что такое page hit и page miss?</p>\n","answer":"<p><strong>Ответ:</strong> Hit означает пригодная копия найдена на конкретном уровне, miss требует следующего уровня/источника. Указать DB buffer/OS cache/CDN/device границу: высокий hit rate одного слоя не означает отсутствие дорогих misses другого.</p>\n<p><strong>Источник:</strong> <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside\">Azure Architecture: Cache-Aside</a></p>\n","group":"🔹 Caching (buffer pool)","line":1742},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:15a26d6914ef85cf:1","question":"<p>(L1 [T]) Почему buffer pool влияет и на reads, и на writes?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1749},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7166b734b4c39252:1","question":"<p>(L1 [T]) Что такое dirty page в buffer pool?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Dirty page изменена в памяти и ещё не приведена к устойчивому backing state. Для DB pages нужен WAL-before-data, для OS cache — writeback/sync по контракту; один dirty flag не содержит всего recovery protocol.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">Linux man-pages: open and O_DIRECT</a></p>\n","group":"🔹 Caching (buffer pool)","line":1756},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:02e37974b2c31f6b:1","question":"<p>(L1 [T]) Почему eviction policy важна?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1763},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:67e005ef5ebba451:1","question":"<p>(L1 [T]) Что такое LRU и почему её любят в теории?</p>\n","answer":"<p><strong>Ответ:</strong> LRU сохраняет недавно использованные, LFU — частые с aging, Clock приближает recency с меньшей metadata работой. Scan pollution, approximation и pinned pages меняют эффективность; выбирать по hit/bytes/latency, а не названию.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a></p>\n","group":"🔹 Caching (buffer pool)","line":1770},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:991f2d8399ab7b42:1","question":"<p>(L1 [T]) Почему чистый LRU не всегда хорош для БД?</p>\n","answer":"<p><strong>Ответ:</strong> LRU сохраняет недавно использованные, LFU — частые с aging, Clock приближает recency с меньшей metadata работой. Scan pollution, approximation и pinned pages меняют эффективность; выбирать по hit/bytes/latency, а не названию.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a></p>\n","group":"🔹 Caching (buffer pool)","line":1777},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f39a0d0c1d750e9d:1","question":"<p>(L1 [T]) Почему большой buffer pool не гарантирует хорошую производительность?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1784},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:257bdadfb6d54f2f:1","question":"<p>(L1 [P]) Реализовать buffer pool для fixed-size pages</p>\n","answer":"<p><strong>Ответ:</strong> Map page_id→frames с pin/dirty/generation и coalesced load, bounded replacement. I/O не выполняется с произвольным освобождённым frame, dirty flush ждёт durable pageLSN; test concurrent load/evict и I/O failure.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1791},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1cff5dbba5eb36d4:1","question":"<p>(L1 [P]) Реализовать page table: page_id → frame</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать page table, pin/unpin, bounded frames, loader coalescing и LRU/Clock policy. Flush dirty frame только после durable pageLSN, смену mapping синхронизировать; проверять eviction при живых readers и ошибках I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1798},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4c39af2833fd6cab:1","question":"<p>(L1 [P]) Реализовать LRU eviction</p>\n","answer":"<p><strong>Ответ:</strong> Hash map key→iterator и двусвязный список: hit перемещает в начало, eviction удаляет хвост. Все изменения связаны; pinned/in-flight записи требуют отдельной обработки.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a></p>\n","group":"🔹 Caching (buffer pool)","line":1805},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:574769e00a84f004:1","question":"<p>(L1 [P]) Реализовать dirty flag и flush dirty pages</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать dirty unpinned candidate, зафиксировать согласованный image/LSN, дождаться durable WAL и выполнить write. Проверить errors и re-dirty race перед очисткой dirty flag; ограничить background budget foreground latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a></p>\n","group":"🔹 Caching (buffer pool)","line":1812},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e72117ce1bb592b9:1","question":"<p>(L1 [P]) Реализовать hit/miss counters</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать page table, pin/unpin, bounded frames, loader coalescing и LRU/Clock policy. Flush dirty frame только после durable pageLSN, смену mapping синхронизировать; проверять eviction при живых readers и ошибках I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1819},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:835c7e015fc34c35:1","question":"<p>(L2 [T]) Почему scans могут вытеснять hot pages?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1826},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ef0311766b0f359e:1","question":"<p>(L2 [T]) Что такое buffer pool thrashing?</p>\n","answer":"<p><strong>Ответ:</strong> Control loop без hysteresis/cooldown может многократно переносить данные/ресурсы между решениями. Использовать стабильное окно, разные пороги входа/выхода и budget изменений; учитывать delayed metrics и стоимость прогрева. Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1833},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:842f587662f0f214:1","question":"<p>(L2 [T]) Почему CLOCK/2Q/LRU-K часто лучше простого LRU?</p>\n","answer":"<p><strong>Ответ:</strong> LRU сохраняет недавно использованные, LFU — частые с aging, Clock приближает recency с меньшей metadata работой. Scan pollution, approximation и pinned pages меняют эффективность; выбирать по hit/bytes/latency, а не названию.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a></p>\n","group":"🔹 Caching (buffer pool)","line":1840},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:df3cba017cae41e2:1","question":"<p>(L2 [T]) Что такое pin/unpin page?</p>\n","answer":"<p><strong>Ответ:</strong> Pin удерживает frame/страницу от reuse пока caller её использует; unpin отпускает удержание. Pin не равен latch для содержимого, а забытый unpin может исчерпать pool даже при хорошем hit rate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a></p>\n","group":"🔹 Caching (buffer pool)","line":1847},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1d41f1463b2566ba:1","question":"<p>(L2 [T]) Почему buffer pool должен быть concurrency-safe?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1854},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c6d8678062774cfc:1","question":"<p>(L2 [T]) Как background flusher помогает write path?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1861},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:dde84b2c89b64c68:1","question":"<p>(L2 [T]) Почему checkpoint pressure влияет на buffer pool behavior?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1868},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ffa8acb8b73f476b:1","question":"<p>(L2 [T]) Что такое free list?</p>\n","answer":"<p><strong>Ответ:</strong> Free list содержит доступные frames/slots/blocks в конкретной границе allocator/pool. Выдача/возврат должны сохранять ownership, alignment и generation, быть concurrency-safe и не возвращать ещё pinned/live storage.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://eel.is/c++draft/mem.res\">C++ working draft: Memory resources</a></p>\n","group":"🔹 Caching (buffer pool)","line":1875},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:419baf82f6fa2431:1","question":"<p>(L2 [T]) Почему buffer pool sizing связан с workload, а не только с объёмом RAM?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1882},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c60c8cda990f8e95:1","question":"<p>(L2 [T]) Почему double caching с ОС может быть болезненной?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1889},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e8ee0cf6817e111a:1","question":"<p>(L2 [P]) Реализовать CLOCK eviction</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать map key→replacement metadata и byte capacity; hit обновляет policy, victim исключает pinned/in-flight entries. Dirty victim flush следует WAL-before-data; test scan pollution, concurrency, failed writeback и exhaustion.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1896},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:f765d1acebe4d860:1","question":"<p>(L2 [P]) Реализовать scan-resistant policy</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать page table, pin/unpin, bounded frames, loader coalescing и LRU/Clock policy. Flush dirty frame только после durable pageLSN, смену mapping синхронизировать; проверять eviction при живых readers и ошибках I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1903},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5c7b3e46bd532e69:1","question":"<p>(L2 [P]) Реализовать pin count и запрет eviction pinned pages</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать map key→replacement metadata и byte capacity; hit обновляет policy, victim исключает pinned/in-flight entries. Dirty victim flush следует WAL-before-data; test scan pollution, concurrency, failed writeback и exhaustion.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1910},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:05b80cb22ecfcfc5:1","question":"<p>(L2 [P]) Реализовать background flush thread</p>\n","answer":"<p><strong>Ответ:</strong> Committers публикуют target LSN в bounded queue, один flusher пишет и sync общий префикс. После успеха продвинуть durable watermark и разбудить только покрытых waiters; error/cancel/restart не должны давать ранний ACK или lost wakeup.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://man7.org/linux/man-pages/man2/fsync.2.html\">Linux man-pages: fsync</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a></p>\n","group":"🔹 Caching (buffer pool)","line":1917},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2d6601bb13469389:1","question":"<p>(L2 [P]) Реализовать buffer pool benchmark: hot set + scan workload</p>\n","answer":"<p><strong>Ответ:</strong> Map page_id→frames с pin/dirty/generation и coalesced load, bounded replacement. I/O не выполняется с произвольным освобождённым frame, dirty flush ждёт durable pageLSN; test concurrent load/evict и I/O failure.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"🔹 Caching (buffer pool)","line":1924},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8f2ddd5fddda276f:1","question":"<p>(L2 [D]) Почему после большого scan OLTP latency выросла?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1931},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:bf4b5dc6a5b8c138:1","question":"<p>(L2 [D]) Почему hit rate хороший, а запросы всё равно медленные?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1938},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ba085f400ff07860:1","question":"<p>(L2 [D]) Почему buffer pool постоянно грязный и flush не успевает?</p>\n","answer":"<p><strong>Ответ:</strong> Dirty read наблюдает незавершённое изменение; dirty write перезаписывает его до исхода владельца. Это разные аномалии; проверять complete history, а не только final значения после commit. Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/transaction-iso.html\">PostgreSQL: Transaction isolation</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1945},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:de8b25989eb6fce9:1","question":"<p>(L2 [D]) Почему mutex/locks внутри buffer pool стали bottleneck?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1952},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8f3be488d72e26e2:1","question":"<p>(L2 [D]) Почему после увеличения cache size performance почти не изменилась?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1959},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e5f7e87299c0b3da:1","question":"<p>(L3 [T]) Как проектировать sharded/partitioned buffer pool под many-core CPU?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1966},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ccb85f25af2ee91c:1","question":"<p>(L3 [T]) Как replacement policy должна учитывать scans vs point lookups?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1973},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c20833240fce4e64:1","question":"<p>(L3 [T]) Как NUMA влияет на buffer pool design?</p>\n","answer":"<p><strong>Ответ:</strong> На NUMA стоимость доступа зависит от размещения страницы относительно выполняющего thread. First-touch, affinity и memory policy важны вместе; pinning CPU без переноса данных не гарантирует locality. Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1980},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4db89e8db0e8efa0:1","question":"<p>(L3 [T]) Как buffer pool взаимодействует с WAL, checkpoint и recovery?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1987},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d327fbf2b84fcd62:1","question":"<p>(L3 [T]) Почему page latch, pin count и eviction policy надо рассматривать вместе?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Pin удерживает frame/страницу от reuse пока caller её использует; unpin отпускает удержание. Pin не равен latch для содержимого, а забытый unpin может исчерпать pool даже при хорошем hit rate.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":1994},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:4f212725b0250731:1","question":"<p>(L3 [T]) Как page temperature / frequency statistics улучшают caching decisions?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2001},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:8a7c253b79d3bd2b:1","question":"<p>(L3 [T]) Как huge pages, alignment и allocator choices влияют на buffer pool?</p>\n","answer":"<p><strong>Ответ:</strong> TLB кэширует translations, и большой случайный working set повышает translation misses/page walks. Huge pages увеличивают охват TLB, но требуют оценки fragmentation, allocation stalls и реального выигрыша. Alignment влияет на допустимость и стоимость loads, пересечение lines/pages и SIMD. Over-aligned buffer требует подходящего allocator; больше padding не всегда лучше из-за footprint/cache pressure.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://eel.is/c++draft/library\">C++ working draft: Library</a>; <a href=\"https://docs.kernel.org/kernel-hacking/false-sharing.html\">Linux kernel: False sharing</a></p>\n","group":"🔹 Caching (buffer pool)","line":2008},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:89ff3abb143a4734:1","question":"<p>(L3 [T]) Почему compressed pages в cache — отдельный trade-off?</p>\n","answer":"<p><strong>Ответ:</strong> Compression уменьшает bytes/IO ценой encode/decode CPU и минимальной единицы доступа. Codec/block size выбирают по input, point/range path и p99; уже сжатые/высокоэнтропийные данные могут почти не уменьшаться.</p>\n<p><strong>Источник:</strong> <a href=\"https://parquet.apache.org/docs/file-format/\">Apache Parquet: File format</a>; <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a></p>\n","group":"🔹 Caching (buffer pool)","line":2015},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7a0d573191171841:1","question":"<p>(L3 [T]) Как измерять не только hit ratio, но и useful hit ratio / eviction pain?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool отображает page IDs в frames с pin/ref count, dirty state и replacement metadata. Используемую страницу нельзя переиспользовать; dirty victim требует write-ahead ordering и безопасного завершения I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2022},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1d426ef187ac4154:1","question":"<p>(L3 [T]) Почему buffer pool — это не просто cache, а центр всей storage concurrency?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2029},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:c786c5a7d888c2f5:1","question":"<p>(L3 [P]) Реализовать sharded buffer pool</p>\n","answer":"<p><strong>Ответ:</strong> Map page_id→frames с pin/dirty/generation и coalesced load, bounded replacement. I/O не выполняется с произвольным освобождённым frame, dirty flush ждёт durable pageLSN; test concurrent load/evict и I/O failure.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2036},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e2edfed669f972a7:1","question":"<p>(L3 [P]) Реализовать LRU-K или 2Q</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать map key→replacement metadata и byte capacity; hit обновляет policy, victim исключает pinned/in-flight entries. Dirty victim flush следует WAL-before-data; test scan pollution, concurrency, failed writeback и exhaustion.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/develop/reference/eviction/\">Redis: Key eviction</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2043},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a54df8342d0db4c2:1","question":"<p>(L3 [P]) Реализовать per-page access frequency tracking</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать page table, pin/unpin, bounded frames, loader coalescing и LRU/Clock policy. Flush dirty frame только после durable pageLSN, смену mapping синхронизировать; проверять eviction при живых readers и ошибках I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2050},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1b750ee156169c7f:1","question":"<p>(L3 [P]) Реализовать flush scheduler с write coalescing</p>\n","answer":"<p><strong>Ответ:</strong> Реализовать page table, pin/unpin, bounded frames, loader coalescing и LRU/Clock policy. Flush dirty frame только после durable pageLSN, смену mapping синхронизировать; проверять eviction при живых readers и ошибках I/O.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2057},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:e9187b8a1e50ccf2:1","question":"<p>(L3 [P]) Реализовать observability: hit ratio, dirty ratio, eviction rate, flush lag, latch contention</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать dirty unpinned candidate, зафиксировать согласованный image/LSN, дождаться durable WAL и выполнить write. Проверить errors и re-dirty race перед очисткой dirty flag; ограничить background budget foreground latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a></p>\n","group":"🔹 Caching (buffer pool)","line":2064},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ca3cde67c860476b:1","question":"<p>(L3 [D]) Как доказать, что bottleneck в buffer pool contention, а не в диске?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2071},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:36d2c297119d74ee:1","question":"<p>(L3 [D]) Почему после смены eviction policy p50 улучшился, а p99 ухудшился?</p>\n","answer":"<p><strong>Ответ:</strong> Tail определяется очередями, редкими stalls и fan-out: хороший p50 не исключает плохой p99. Сопоставить временную линию с maintenance, topology changes и resource saturation; retry/hedging добавляют нагрузку и требуют бюджета. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/the-tail-at-scale/\">Dean, Barroso: The Tail at Scale</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2078},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cb2348105a0e0c7e:1","question":"<p>(L3 [D]) Как расследовать write stall, вызванный нехваткой clean pages?</p>\n","answer":"<p><strong>Ответ:</strong> Stall/backpressure ограничивает приём, когда memtables/L0/очередь опережают обслуживание. Это защищает bounded resources, но пиковая latency растёт; бесконечная очередь лишь откладывает отказ и увеличивает recovery debt. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2085},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:35c92f422fa3263f:1","question":"<p>(L3 [D]) Почему хороший hit ratio скрывает плохую locality и высокие latch costs?</p>\n","answer":"<p><strong>Ответ:</strong> Locality сокращает RTT/shipping, но должна учитывать freshness, quorum и fault domains. Ближайший node не всегда eligible; приближение одного leader может увеличить remote reads/влияние на других tenants. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/deployment-stamp\">Azure Architecture: Deployment stamps</a>; <a href=\"https://research.google/pubs/spanner-googles-globally-distributed-database/\">Google: Spanner paper</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2092},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d11658700a8ed88e:1","question":"<p>(L3 [D]) Как отличить page cache issue ОС от собственного buffer pool issue БД?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Измерить hits/misses по типу страниц, pins, dirty backlog, eviction stalls и load latency. Отличить cache БД от Linux page cache; общий hit rate может скрывать misses горячего tenant или leaf pages.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2099},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ca41eaabddcd59c3:1","question":"<p>(L4 [S]) Когда БД стоит полагаться на OS page cache, а когда нужен мощный buffer pool?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Рекомендация:</strong> Распределить память между data/index/filter/working buffers и ОС, учитывать cgroups и concurrency. Кэшировать измеренный working set, ограничить scan pollution и проверить cold recovery/массовый прогрев.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2106},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:98bd91ee985a7914:1","question":"<p>(L4 [S]) Как выбирать memory budget между buffer pool, execution memory и OS cache?</p>\n","answer":"<p><strong>Ответ:</strong> Planner search может строиться снизу вверх dynamic programming либо сверху вниз через memo/rules и physical requirements. Search space grows combinatorially, поэтому pruning/budgets/heuristics обязательны; semantic equivalence проверяется отдельно от cost. Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Рекомендация:</strong> Распределить память между data/index/filter/working buffers и ОС, учитывать cgroups и concurrency. Кэшировать измеренный working set, ограничить scan pollution и проверить cold recovery/массовый прогрев.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a>; <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2115},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:39f76f687ca84813:1","question":"<p>(L4 [S]) Как проектировать buffer pool для mixed OLTP + analytical workload?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Рекомендация:</strong> Распределить память между data/index/filter/working buffers и ОС, учитывать cgroups и concurrency. Кэшировать измеренный working set, ограничить scan pollution и проверить cold recovery/массовый прогрев.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2124},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:71d118e602a043b4:1","question":"<p>(L4 [S]) Как строить roadmap cache optimizations без переусложнения архитектуры?</p>\n","answer":"<p><strong>Ответ:</strong> Распределить память между data/index/filter/working buffers и ОС, учитывать cgroups и concurrency. Кэшировать измеренный working set, ограничить scan pollution и проверить cold recovery/массовый прогрев.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2133},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:30534189d769be8d:1","question":"<p>(L4 [S]) Как объяснять команде, что высокий hit ratio сам по себе не равен хорошей производительности?</p>\n","answer":"<p><strong>Ответ:</strong> Распределить память между data/index/filter/working buffers и ОС, учитывать cgroups и concurrency. Кэшировать измеренный working set, ограничить scan pollution и проверить cold recovery/массовый прогрев.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Caching (buffer pool)","line":2140},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:1229623e9255875d:1","question":"<p>(L2 [T]) Как query planning, CBO и execution plans связаны между собой?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2151},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:712b1f2c71d6befa:1","question":"<p>(L2 [T]) Почему плохой cardinality estimate часто ведёт и к плохому index selection, и к плохому execution plan?</p>\n","answer":"<p><strong>Ответ:</strong> Кардинальность означает число разных значений/комбинаций либо размер результата — границу нужно назвать. В TSDB каждый новый label set создаёт series state; в query planning cardinality error меняет memory/join решения.</p>\n<p><strong>Источник:</strong> <a href=\"https://prometheus.io/docs/practices/instrumentation/\">Prometheus: Instrumentation practices</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2158},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:ae42625cd3d354bc:1","question":"<p>(L2 [T]) Как buffer pool/page cache меняют реальную стоимость plan operators?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Access path — физический способ получить строки, например sequential/index scan; plan operator выполняет scan/filter/join/sort/aggregate. План связывает их и requirements порядка/распределения; одинаковый результат допускает разные costs.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cross-topic вопросы","line":2165},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:6230a86c8a7d690c:1","question":"<p>(L2 [T]) Почему optimizer не может идеально предсказывать performance без runtime feedback?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2172},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:cc4e6c1fa600cdaf:1","question":"<p>(L2 [T]) Как MVCC visibility cost и heap fetches искажают “теоретически хороший” index plan?</p>\n","answer":"<p><strong>Ответ:</strong> MVCC сохраняет версии и выбирает видимую по snapshot/transaction state. Readers меньше блокируют writers, но conflicts писателей, version storage и GC остаются; старейший активный snapshot ограничивает безопасную очистку.</p>\n<p><strong>Пример:</strong> Snapshot S видит версию commit_seq=10 и не видит новую commit_seq=20, если её boundary равна 15.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://www.postgresql.org/docs/current/routine-vacuuming.html\">PostgreSQL: Routine vacuuming</a></p>\n","group":"🔹 Cross-topic вопросы","line":2179},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7b5265ea4afd1cc3:1","question":"<p>(L2 [T]) Почему performance debugging всегда требует связки: SQL + plan + stats + cache + I/O?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2188},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:a304774e07cb80bc:1","question":"<p>(L2 [T]) Как Linux page cache, buffer pool и storage latency вместе формируют observed query time?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a></p>\n","group":"🔹 Cross-topic вопросы","line":2195},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:39910bbe9169d3e7:1","question":"<p>(L2 [T]) Почему high CPU query может быть следствием planner mistake, а не “медленного железа”?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2202},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:978b1e0b78914828:1","question":"<p>(L2 [T]) Почему оптимизация одного запроса может ухудшить общий workload mix?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2209},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b0a3763e60ad4ba5:1","question":"<p>(L2 [T]) Почему production performance issues редко решаются “добавить индекс” в один шаг?</p>\n","answer":"<p><strong>Ответ:</strong> Planner строит эквивалентные logical/physical планы и выбирает по оценённым rows/cost. Плохая cardinality, correlations, неверная selectivity или дорогой data shipping могут сделать выбранный план хуже фактической альтернативы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2216},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:5f3dfd9c485a9be3:1","question":"<p>(L2 [P]) Реализовать mini-engine: planner + CBO + executor + buffer pool</p>\n","answer":"<p><strong>Ответ:</strong> Map page_id→frames с pin/dirty/generation и coalesced load, bounded replacement. I/O не выполняется с произвольным освобождённым frame, dirty flush ждёт durable pageLSN; test concurrent load/evict и I/O failure.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2223},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b0ce4356026180b0:1","question":"<p>(L2 [P]) Реализовать dashboard: planning time, execution time, actual rows, buffer hits, spills</p>\n","answer":"<p><strong>Ответ:</strong> Экспортировать counters/gauges/histograms по stages и bounded shard/region/workload dimensions; operation IDs оставить logs/traces. Добавить queue age, completion/error rates и нужные версии/LSN, проверить сигнал known fault и отдельно loss/sampling telemetry.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a></p>\n","group":"🔹 Cross-topic вопросы","line":2230},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:fcb6b99cf58cd247:1","question":"<p>(L2 [P]) Реализовать plan regression test suite на synthetic workloads</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2237},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:2d274f740a104c1e:1","question":"<p>(L2 [P]) Реализовать what-if experiments: add index / change stats / shrink cache</p>\n","answer":"<p><strong>Ответ:</strong> Сформировать кандидаты из WHERE/JOIN/ORDER BY, выбрать equality-prefix и range/order suffix, проверить EXPLAIN с фактическими rows. Измерить read gain вместе с size, writes и concurrent build locks.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🔹 Cross-topic вопросы","line":2244},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:048d03b8c0545c37:1","question":"<p>(L2 [P]) Реализовать perf harness: hot cache vs cold cache vs mixed workload</p>\n","answer":"<p><strong>Ответ:</strong> Описать AST и scan/filter/project/join/sort, перечислить допустимые paths и оценить rows/cost. Сравнивать результаты с прямым executor, а оценки — с actual execution; semantic rewrites не должны менять NULL/outer join/volatile поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2251},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7f9375b0d0c88d12:1","question":"<p>(L3 [D]) Почему после добавления индекса p50 улучшился, а cluster-wide throughput упал?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2258},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b9fcf57dfbd3989c:1","question":"<p>(L3 [D]) Почему planner стал чаще выбирать full scan после роста таблицы?</p>\n","answer":"<p><strong>Ответ:</strong> Seq scan может быть оптимален для большой доли строк/малой таблицы, index scan добавляет probes и heap fetch. Сравнивать actual rows/loops/bytes и cache state; «индекс существует» не является правилом обязательного использования. Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2265},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:b5e368fe28d040ca:1","question":"<p>(L3 [D]) Как доказать, что bottleneck в optimizer stats, а не в buffer pool size?</p>\n","answer":"<p><strong>Ответ:</strong> Buffer pool держит page frames с mapping, pin count и dirty state; pinned frame нельзя переиспользовать. Для dirty victim WAL должен стать durable до data flush, а concurrent loader/evictor обязаны согласовать page generation. Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/storage.html\">PostgreSQL: Database physical storage</a>; <a href=\"https://www.postgresql.org/docs/current/wal-intro.html\">PostgreSQL: Write-Ahead Logging</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2272},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:644705ade3d5afe6:1","question":"<p>(L3 [D]) Почему explain plan хороший, но запрос всё равно unstable по latency?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2279},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:3ad77bd022da419e:1","question":"<p>(L3 [D]) Как расследовать инцидент “SQL тот же, схема та же, железо то же, а производительность внезапно хуже”?</p>\n","answer":"<p><strong>Ответ:</strong> Снять EXPLAIN (ANALYZE, BUFFERS) с реальными параметрами, сравнить estimated/actual rows и loops. Найти первый большой промах, spills, лишний fan-out/scan и stale statistics; ANALYZE изменяющего SQL реально выполняет изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2286},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:0bf56d46764395e1:1","question":"<p>(L4 [S]) Как строить performance engineering process для своей БД, а не тушить запросы по одному?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2293},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:dd4da5082ab4cf47:1","question":"<p>(L4 [S]) Какие метрики optimizer/planner/cache нужно собирать с первого дня?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны metrics и traces по shard/tenant/region/stage с ограниченной cardinality, а не только общий health. Разделять queue wait, service, I/O, replication и retries, сохранять operation/epoch context без утечки payload/секретов.</p>\n<p><strong>Рекомендация:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2300},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:56ad5890810661c5:1","question":"<p>(L4 [S]) Как балансировать complexity optimizer-а и предсказуемость системы?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2309},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:7b85414ad9f73149:1","question":"<p>(L4 [S]) Как проектировать observability, чтобы junior/middle инженеры тоже могли читать execution plans осмысленно?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны metrics и traces по shard/tenant/region/stage с ограниченной cardinality, а не только общий health. Разделять queue wait, service, I/O, replication и retries, сохранять operation/epoch context без утечки payload/секретов.</p>\n<p><strong>Рекомендация:</strong> Начать с good/eligible SLI и freshness/durability indicators, затем диагностические dimensions. Назначить владельцев/runbooks и проверить alerts на drills, контролируя стоимость и конфиденциальность telemetry.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/monitoring-distributed-systems/\">Google SRE: Monitoring Distributed Systems</a>; <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a></p>\n","group":"🔹 Cross-topic вопросы","line":2316},{"id":"content/09_database_and_storage/09_performance_and_optimisation.md:d007b8cb4ea81113:1","question":"<p>(L4 [S]) Как объяснить команде, что производительность БД — это результат взаимодействия planner, executor, indexes, cache и I/O, а не “одной магической настройки”?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизировать важные workload classes, а не один удачный query. Управлять statistics, plan stability и observability; hints/forced paths использовать только с измеренным основанием и rollback, а не вместо исправления модели/запроса.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a>; <a href=\"https://www.postgresql.org/docs/current/planner-stats.html\">PostgreSQL: Planner statistics</a></p>\n","group":"🔹 Cross-topic вопросы","line":2325}];
